<script setup>
import HallOfFameWall from './HallOfFameWall.vue'
import DashboardDailyPlanner from './DashboardDailyPlanner.vue'
import { computed, ref, watch, onBeforeUnmount } from 'vue'
import {storeToRefs} from 'pinia'
import {useTeamStore} from '@/store/team'
import {useAxiosAuth} from '@/composables/axios-auth'
const hallOfFame = ref(null)
const {team} = storeToRefs(useTeamStore())
const {axiosGet} = useAxiosAuth()
const activity = ref({}), activityError = ref(''), activityLoading = ref(false)
let activityGeneration = 0
const activityTime = value => value ? new Date(value).toLocaleString(undefined, {month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}) : 'Not recorded'
const recentlyLoggedIn = p => { const time = Date.parse(activity.value[p.id]?.last_login_at); return Number.isFinite(time) && time <= Date.now() && Date.now() - time < 86400000 }
async function loadActivity() {
  const seq = ++activityGeneration, id = team.value?.id_team ?? team.value?.id
  activity.value = {}; activityError.value = ''; activityLoading.value = !!id
  if (!id) return
  try { const {data} = await axiosGet(`coach/teams/${encodeURIComponent(id)}/roster-activity`); if (seq === activityGeneration) activity.value = Object.fromEntries(data.data.map(row => [row.id,row])) }
  catch { if (seq === activityGeneration) activityError.value = 'Activity unavailable' }
  finally { if (seq === activityGeneration) activityLoading.value = false }
}
watch(() => team.value?.id_team ?? team.value?.id, loadActivity, {immediate:true})
onBeforeUnmount(() => {activityGeneration++})
const props = defineProps({players: Array, rows: Array, categories: Array, sessions: Array, sessionTypes: Object, loading: Boolean, performanceLoading: Boolean, sessionsLoading: Boolean, selectedKey: String, teamName: String, leaderboardError: String, leaderMode: String, leadersLoading: Boolean})
const emit = defineEmits(['select-performance', 'player', 'player-metrics', 'session', 'roster', 'sessions', 'retry-leaders', 'leader-mode'])
const search = ref(''), rosterFilter = ref('All'), featuredId = ref(null), sessionFilter = ref(''), expanded = ref(null), discipline = ref('All')
const matchRole = (p, role) => role === 'All' || (role === 'Pitchers' ? p.scores?.bullpen != null : p.scores?.batting != null)
const roster = computed(() => (props.players || []).filter(p => p.name.toLowerCase().includes(search.value.toLowerCase()) && matchRole(p, rosterFilter.value)))
const featured = computed(() => props.players?.find(p => p.id === featuredId.value) || props.players?.[0])
watch(() => props.players, () => { if (!props.players?.some(p => p.id === featuredId.value)) featuredId.value = props.players?.[0]?.id }, {immediate: true})
function cycle(step) { const list = props.players || []; if (list.length) featuredId.value = list[(list.findIndex(p => p.id === featured.value?.id) + step + list.length) % list.length].id }
const value = v => v == null || v === '' ? '—' : v
const tiles = p => [{label: 'EV', value: p?.top_ev_mph, unit: 'mph'}, {label: 'BAT', value: p?.scores?.batting}, {label: 'PITCH', value: p?.scores?.bullpen}, {label: 'OVR', value: p?.scores?.overall}]
const visibleRows = computed(() => (props.rows || []).filter(r => discipline.value === 'All' || (discipline.value === 'Hitting' ? ['batting','ev','cage'].includes(r.key) : ['bullpen','lt','wb'].includes(r.key))))
const sessionsShown = computed(() => (props.sessions || []).filter(s => !sessionFilter.value || s._type === sessionFilter.value))
const todayCount = computed(() => (props.sessions || []).filter(s => { const d = new Date(s.created_at); return !Number.isNaN(d.getTime()) && d.toDateString() === new Date().toDateString() }).length)
const date = s => { const d = new Date(s.created_at || s.updated_at); return Number.isNaN(d.getTime()) ? '—' : d.toLocaleDateString(undefined, {month:'short', day:'numeric', year:'numeric'}) }
const sessionPlayer = s => s.lineup?.[0]?.name?.full || s.lineup?.[0]?.user?.profile?.first_name || 'Team session'
const featuredCategory = computed(() => props.categories?.find(c => c.featured?.id === featured.value?.id))
const trend = computed(() => {
  const values = (featuredCategory.value?.rows.find(r => r.id === featured.value?.id)?.spark || []).filter(v => v !== null && Number.isFinite(Number(v))).map(Number)
  if (values.length < 2) return null
  const min = Math.min(...values), max = Math.max(...values)
  return {points: values.map((v,i) => `${12+i*236/(values.length-1)},${90-(v-min)*70/(max-min||1)}`).join(' '), min, max}
})
const featuredEvidence = computed(() => featuredCategory.value?.featured)
</script>
<template>
  <div class="coach-home">
    <section class="welcome"><div><h1>Welcome Back, Coach</h1><p>Data-driven development for the next generation.</p></div><div class="welcome-stat"><span class="stat-icon">▣</span><div><small>Today · recent activity</small><strong>{{ todayCount }} Sessions</strong><small>{{ teamName || 'Your team' }}</small></div></div><blockquote>“Better Data.<br>Bigger Players.”<small>— FMTRX</small></blockquote></section>
    <div class="overview-grid">
      <section class="panel roster"><header><h2>Roster</h2><button :disabled="activityLoading" @click="loadActivity" aria-label="Refresh player activity">↻</button><button @click="emit('roster')" class="red-link">View All →</button></header><input v-model="search" aria-label="Search roster" placeholder="⌕  Search players…"><div class="filters"><button v-for="f in ['All','Hitters','Pitchers']" :key="f" :class="{active:rosterFilter===f}" @click="rosterFilter=f">{{ f }} ({{ players?.filter(p=>matchRole(p,f)).length || 0 }})</button></div><p v-if="loading" role="status">Loading roster…</p><div v-else class="roster-scroll"><button v-for="p in roster" :key="p.id" class="athlete" :class="{chosen:featured?.id===p.id}" @click="featuredId=p.id; emit('player-metrics',p)" :aria-label="`Open metrics for ${p.name}`"><img v-if="p.picture" :src="p.picture" :alt="p.name"><span v-else class="avatar">{{ p.name?.slice(0,1) }}</span><div class="athlete-body"><small>{{ p.jersey != null ? '#'+p.jersey : 'Player' }}</small><strong>{{ p.name }}</strong><span class="activity-login" :class="{recent:recentlyLoggedIn(p)}">{{ activityLoading ? 'Loading activity…' : activityError || (recentlyLoggedIn(p) ? '● Logged in within 24h' : 'Last login: ' + activityTime(activity[p.id]?.last_login_at)) }}</span>
              <small v-if="recentlyLoggedIn(p)">{{ activityTime(activity[p.id]?.last_login_at) }}</small>
              <small v-if="activity[p.id]?.profile_updated_at" class="activity-note">Profile updated · {{ activityTime(activity[p.id].profile_updated_at) }}</small>
              <small v-if="activity[p.id]?.workout_completed_at" class="activity-note">Workout completed · {{ activityTime(activity[p.id].workout_completed_at) }}</small>
              <small v-if="activity[p.id]?.session_completed_at" class="activity-note">Session completed · {{ activityTime(activity[p.id].session_completed_at) }}</small>
              <div class="mini-metrics"><span v-for="t in tiles(p).filter(t=>t.label!=='PITCH')" :key="t.label"><small>{{ t.label }}</small><b>{{ value(t.value) }}</b></span></div></div></button><p v-if="!roster.length">No matching players.</p></div></section>
      <div class="dashboard-workout-column"><DashboardDailyPlanner /></div>
      <section class="panel performance"><header><h2>Performance Review</h2><small>Last 10 sessions</small></header><div class="filters"><button v-for="f in ['All','Hitting','Pitching / Throwing']" :key="f" :class="{active:discipline===f}" @click="discipline=f">{{ f }}</button></div><p v-if="performanceLoading" role="status">Loading performance…</p><div class="score-list"><button v-for="r in visibleRows" :key="r.key" :class="{current:selectedKey===r.key}" @click="emit('select-performance',r.key)"><span :style="{color:r.dot}">◈</span><span>{{ r.label }} <small>{{ r.abbr }}</small></span><div class="track"><i :style="{width:Math.min(100,Math.max(0,r.score||0))+'%',background:r.dot}"></i></div><strong :style="{color:r.dot}">{{ value(r.score) }}</strong></button></div><slot name="performance" /></section>
      <aside class="feature-column"><section class="panel"><header><h2>Featured Athlete</h2><div><button aria-label="Previous athlete" @click="cycle(-1)" :disabled="!players?.length">‹</button><button aria-label="Next athlete" @click="cycle(1)" :disabled="!players?.length">›</button></div></header><template v-if="featured"><div class="portrait"><img v-if="featured.picture" :src="featured.picture" :alt="featured.name"><div v-else class="portrait-placeholder">{{ featured.name?.slice(0,1) }}</div><div class="portrait-caption"><small>{{ featured.jersey != null ? '#'+featured.jersey : teamName }}</small><h3>{{ featured.name }}</h3><p>{{ featured.height_ft != null ? featured.height_ft+'′ '+(featured.height_in||0)+'″' : 'Height —' }} · {{ value(featured.weight) }} lbs</p></div></div><div class="feature-metrics"><div v-for="t in tiles(featured)" :key="t.label"><small>{{ t.label }}</small><strong>{{ value(t.value) }}</strong></div></div><p v-if="featuredEvidence?.insight" class="insight">{{ featuredEvidence.insight }}</p><div class="feature-summary"><small>PLAYER PERFORMANCE</small><p>{{ featuredCategory?.label || 'Assessment & Development' }}</p><strong>{{ featuredEvidence?.bigValue ?? '—' }} <small>{{ featuredCategory?.unit }}</small></strong><svg v-if="trend" viewBox="0 0 260 110" role="img" :aria-label="`${featuredCategory.label} recent trend, from ${trend.min} to ${trend.max}`"><path d="M12 20H248 M12 55H248 M12 90H248" stroke="#263951"/><polyline :points="trend.points" fill="none" stroke="#ff444c" stroke-width="2.5"/></svg><p>{{ featuredEvidence?.subtitle || 'Open the player profile for detailed results and training history.' }}</p></div><button class="primary full" @click="emit('player', featured)">View Player Profile →</button><RouterLink class="report-link" :to="{path:'/assessment-reports',query:{player:featured.id}}">Assessment Reports →</RouterLink></template><p v-else>Select a team with players to view an athlete.</p></section></aside>
    </div>
    <section class="panel hall-of-fame" aria-labelledby="hall-of-fame-title">
      <header><div><h2 id="hall-of-fame-title">Hall of Fame</h2><p>Celebrate your top players with rotating leaderboards and a full-screen TV presentation.</p></div><button type="button" class="primary" :disabled="leadersLoading || !!leaderboardError || !categories?.length" @click="hallOfFame?.toggleFullscreen()">⛶ Present on TV</button></header>
      <button v-if="leaderboardError" type="button" class="text-link" @click="emit('retry-leaders')">Retry Hall of Fame</button>
      <HallOfFameWall ref="hallOfFame" :categories="categories" :loading="leadersLoading" :error="leaderboardError" />
    </section>
    <section class="panel leaders"><header><div><h2>Top Metrics & Performers</h2><p>Team leaders across key performance categories. Select a player to view their profile.</p></div><button class="red-link" @click="expanded=expanded===null?'all':null">{{ expanded===null ? 'View All Metrics →' : 'Show Top Metrics' }}</button></header><p v-if="leaderboardError" role="alert">{{ leaderboardError }} <button @click="emit('retry-leaders')">Retry</button></p><div class="filters leader-modes"><button :class="{active:leaderMode==='players'}" @click="emit('leader-mode','players')">Team Leaders</button><button :class="{active:leaderMode==='percentiles'}" @click="emit('leader-mode','percentiles')">Percentile Leaders</button></div><slot v-if="leaderMode==='percentiles'" name="percentiles" /><p v-else-if="leadersLoading" role="status">Loading leaders…</p><div v-else class="leader-grid"><article v-for="c in (expanded==='all' || expanded!==null ? categories : categories?.slice(0,4))" :key="c.value"><header><h3 :style="{color:c.color}">{{ c.label }}</h3><small>{{ c.unit }}</small></header><small>{{ c.subtitle || 'Top performers' }}</small><button v-for="(p,i) in c.rows.slice(0,expanded===c.value?25:5)" :key="p.id || i" class="leader-row" @click="emit('player',{id:p.id,name:p.name})"><b>{{ i+1 }}</b><img v-if="p.avatar" :src="p.avatar" alt=""><span>{{ p.name }}</span><strong>{{ p.value }}</strong></button><p v-if="!c.rows.length">No recorded results.</p><button class="full text-link" @click="expanded=expanded===c.value?null:c.value">{{ expanded===c.value?'Show Top 5':'View Full Leaderboard →' }}</button></article></div><p v-if="leaderMode!=='percentiles' && !leadersLoading && !categories?.length && !leaderboardError">Leaderboards appear when team results are recorded.</p></section>
    <section class="panel sessions"><header><div><h2>Recent Sessions</h2><p>Latest training sessions across your team.</p></div><select v-model="sessionFilter" aria-label="Filter recent sessions"><option value="">All Session Types</option><option v-for="type in [...new Set(sessions?.map(s=>s._type))]" :key="type" :value="type">{{ sessionTypes?.[type]?.label || type }}</option></select></header><div class="table-scroll"><table><thead><tr><th>Type</th><th>Date</th><th>Player</th><th>Details</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="session in sessionsShown" :key="session._type+session.id"><td><span class="type-badge">{{ sessionTypes?.[session._type]?.label || session._type }}</span></td><td>{{ date(session) }}</td><td>{{ sessionPlayer(session) }}</td><td>{{ session.lineup?.length || '—' }} participants</td><td>{{ session.is_completed?'Completed':'In progress' }}</td><td><button @click="emit('session',session)">View →</button></td></tr></tbody></table></div><p v-if="sessionsLoading">Loading sessions…</p><p v-else-if="!sessionsShown.length">No matching sessions.</p><button class="text-link" @click="emit('sessions')">View All Sessions →</button></section>
    <footer><strong>FMTR<span>X</span></strong><p>Train Smarter. Play Further.</p><RouterLink to="/settings">Settings</RouterLink></footer>
  </div>
</template>
<style scoped>
